css:
.sl-gallery-3d-stage { padding: 5rem 0; background-color: var(--smartlearn-bg); overflow: hidden; }
.sl-gallery-3d-stage .text-center { text-align: center; }
.sl-gallery-3d-stage .sl-mb-12 { margin-bottom: 3rem; }
.sl-gallery-3d-stage .sl-section-title { font-size: 2.25rem; font-weight: 700; color: var(--smartlearn-text); margin-bottom: 0.5rem; }
.sl-gallery-3d-stage .sl-section-subtitle { font-size: 1.125rem; color: var(--smartlearn-text-muted); }
.sl-gallery-3d-stage .sl-stage-container { position: relative; max-width: 1000px; margin: 0 auto; height: 400px; perspective: 1200px; display: flex; align-items: center; justify-content: center; }
.sl-gallery-3d-stage .sl-stage-item { position: absolute; width: 60%; max-width: 600px; aspect-ratio: 16/9; border-radius: 1rem; overflow: hidden; box-shadow: 0 20px 40px rgba(0,0,0,0.2); transition: all 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94); cursor: pointer; border: 1px solid var(--smartlearn-card-border, rgba(0,0,0,0.1)); }
.sl-gallery-3d-stage .sl-stage-item img { width: 100%; height: 100%; object-fit: cover; }
.sl-gallery-3d-stage .sl-stage-center { transform: translateX(0) translateZ(0) rotateY(0); z-index: 3; filter: brightness(1); }
.sl-gallery-3d-stage .sl-stage-left { transform: translateX(-40%) translateZ(-200px) rotateY(25deg); z-index: 2; filter: brightness(0.6); }
.sl-gallery-3d-stage .sl-stage-right { transform: translateX(40%) translateZ(-200px) rotateY(-25deg); z-index: 2; filter: brightness(0.6); }
/* Reduced motion fallback: flat grid */
@media (prefers-reduced-motion: reduce) {
    .sl-gallery-3d-stage .sl-stage-container { perspective: none; height: auto; flex-direction: column; gap: 2rem; }
    .sl-gallery-3d-stage .sl-stage-item { position: static; width: 100%; transform: none !important; filter: none !important; cursor: default; }
}
@media (max-width: 767px) {
    .sl-gallery-3d-stage .sl-stage-container { perspective: none; height: auto; flex-direction: column; gap: 1rem; padding: 0 1rem; }
    .sl-gallery-3d-stage .sl-stage-item { position: static; width: 100%; transform: none !important; filter: none !important; cursor: default; }
}

js:
(function() {
    const root = document.querySelector('.sl-gallery-3d-stage');
    if (!root) return;
    const items = root.querySelectorAll('.sl-stage-item');
    if(window.matchMedia('(prefers-reduced-motion: reduce)').matches || window.innerWidth < 768) return;

    items.forEach(item => {
        item.addEventListener('click', () => {
            if(document.body.classList.contains('sl-editor-mode')) return;
            const currentCenter = root.querySelector('.sl-stage-center');
            if(currentCenter === item) return;

            // Swap classes based on position
            const clickedClass = item.classList.contains('sl-stage-left') ? 'sl-stage-left' : 'sl-stage-right';
            const centerClass = 'sl-stage-center';

            item.classList.remove(clickedClass);
            item.classList.add(centerClass);

            currentCenter.classList.remove(centerClass);
            currentCenter.classList.add(clickedClass);

            // Cleanup any playing video in the old center
            const oldIframe = currentCenter.querySelector('iframe');
            if(oldIframe) {
                oldIframe.remove();
                const oldPoster = currentCenter.querySelector('.sl-stage-poster');
                const oldPlay = currentCenter.querySelector('.sl-item-play-btn');
                if(oldPoster) oldPoster.style.display = '';
                if(oldPlay) oldPlay.style.display = '';
            }
        });

        // Handle play button
        const playBtn = item.querySelector('.sl-item-play-btn');
        if(playBtn) {
            playBtn.addEventListener('click', (e) => {
                if(document.body.classList.contains('sl-editor-mode')) return;

                const currentCenter = root.querySelector('.sl-stage-center');
                if(currentCenter !== item) return; // Only play if it's the center item

                e.stopPropagation(); // prevent triggering the swap

                const urlEl = item.querySelector('.sl-item-video-url');
                const videoUrl = urlEl ? urlEl.innerText.trim() : '';
                if(!videoUrl) return;

                const poster = item.querySelector('.sl-stage-poster');
                if(poster) poster.style.display = 'none';
                playBtn.style.display = 'none';

                const iframe = document.createElement('iframe');
                iframe.src = videoUrl + (videoUrl.includes('?') ? '&' : '?') + 'autoplay=1';
                iframe.style.position = 'absolute';
                iframe.style.top = '0';
                iframe.style.left = '0';
                iframe.style.width = '100%';
                iframe.style.height = '100%';
                iframe.style.border = 'none';
                iframe.style.zIndex = '10';
                iframe.setAttribute('allow', 'autoplay; fullscreen; encrypted-media');
                iframe.setAttribute('allowfullscreen', 'true');

                item.appendChild(iframe);
            });
        }
    });
})();
